import {remaining,startTimer,pauseTimer,resumeTimer,addTime,formatTime} from './timer.js';
import {TIERS,COLORS,DECKS,shuffle,swap,evaluate,totals,outcome} from './core.js';
import {createTable} from './table.js';
const app=document.querySelector('#app');const KEY='rank-party-v2';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,table=null,saved=null,sound=false,audioContext=null,timerInterval=null;
let setup={names:['Player 1','Player 2','Player 3'],deck:'A little of everything',custom:'',timerSeconds:90};
try{saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version!==2||!Array.isArray(saved.names)||!Array.isArray(saved.history))saved=null;}catch{}
const name=()=>state.names[state.round%state.names.length];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function ping(hit=true){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.type='sine';o.frequency.setValueAtTime(hit?660:220,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(hit?990:165,audioContext.currentTime+.13);g.gain.setValueAtTime(.055,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.23);o.start();o.stop(audioContext.currentTime+.24);}catch{}}
document.querySelector('#rules-button').onclick=()=>document.querySelector('#rules').showModal();document.querySelectorAll('.close,.close-rules').forEach(b=>b.onclick=()=>document.querySelector('#rules').close());document.querySelector('#sound-button').onclick=e=>{sound=!sound;e.currentTarget.textContent=`Sound: ${sound?'on':'off'}`;e.currentTarget.setAttribute('aria-pressed',sound);if(sound)ping();};
function mount(html){clearInterval(timerInterval);timerInterval=null;table?.destroy();table=null;app.innerHTML=html;window.scrollTo({top:0,behavior:'instant'});}
function scene(items,options){table=createTable(document.querySelector('#scene'),items,options);}
function readSetup(){setup.names=[...document.querySelectorAll('.name-input')].map(x=>x.value);setup.deck=document.querySelector('#deck').value;setup.timerSeconds=Number(document.querySelector('#timer-duration').value);if(document.querySelector('#custom'))setup.custom=document.querySelector('#custom').value;}
function renderSetup(){
 mount(`<div class="setup-grid"><section class="hero"><div class="edition">THE GET-TO-KNOW-YOU GAME / VOL. 01</div><h1><span class="hot">BEST</span><span class="small-word"> TO </span><br><span class="cold">WORST.</span></h1><p class="hero-sub">Your favorite. My hard pass.<br>But tonight, <strong>we’re on the same team.</strong></p><div id="scene" class="scene" aria-hidden="true"></div><p class="scene-note">FIVE CARDS. A LITTLE CHAOS. A LOT OF YOU.</p><div class="steps"><span><b>01</b>One person ranks</span><span><b>02</b>Everyone guesses</span><span><b>03</b>Everyone wins. Or loses.</span></div></section><section class="paper"><span class="eyebrow">PULL UP A CHAIR</span><h2>Who gets you best?</h2><p class="intro">One device. Your favorite people.<br>Let’s see how well you know each other.</p>${saved?'<div class="resume">Your table is still waiting.<br><button id="resume">Continue your game →</button></div>':''}<form id="setup-form"><label class="field-label">Who’s at the table? <span>2–8 people</span></label><div class="names">${setup.names.map((n,i)=>`<div class="name-row"><span class="seat">${String(i+1).padStart(2,'0')}</span><input class="name-input" aria-label="Player ${i+1} name" maxlength="20" value="${esc(n)}" placeholder="Enter a name" required><button class="remove" type="button" data-remove="${i}" aria-label="Remove player ${i+1}" ${setup.names.length<=2?'disabled':''}>×</button></div>`).join('')}</div><button class="add" type="button" id="add" ${setup.names.length>=8?'disabled':''}>＋ Add a seat</button><label class="field-label" for="deck">Pick your conversation <span>5 cards per round</span></label><select id="deck">${[...Object.keys(DECKS),'Your own topics'].map(x=>`<option ${x===setup.deck?'selected':''}>${x}</option>`).join('')}</select>${setup.deck==='Your own topics'?`<textarea id="custom" aria-label="Custom topics, one per line" placeholder="One topic per line. Add 5–60 different topics.">${esc(setup.custom)}</textarea>`:''}<label class="field-label" for="timer-duration">Time per turn <span>Ranking &amp; guessing</span></label><select id="timer-duration">${[[0,'No timer'],[60,'1 minute'],[90,'90 seconds'],[120,'2 minutes']].map(([v,label])=>`<option value="${v}" ${setup.timerSeconds===v?'selected':''}>${label}</option>`).join('')}</select><p class="error" id="error" role="alert"></p><button class="primary" type="submit">Take a seat. Let’s play <span>↗</span></button><p class="micro">No sign-up · Pass one device around<br>Everyone ranks once · Ties go to overtime</p></form></section></div>`);
 scene(['Hot pot','Rainy days','Social media','Horror movies','Cilantro'],{demo:true});
 document.querySelector('#add').onclick=()=>{readSetup();setup.names.push(`Player ${setup.names.length+1}`);renderSetup();};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{readSetup();setup.names.splice(Number(b.dataset.remove),1);renderSetup();});document.querySelector('#deck').onchange=()=>{readSetup();renderSetup();};
 document.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();readSetup();const names=setup.names.map(x=>x.trim());let deck=setup.deck==='Your own topics'?[...new Set(setup.custom.split('\n').map(x=>x.trim()).filter(Boolean))]:DECKS[setup.deck];const error=document.querySelector('#error');if(names.some(x=>!x)||new Set(names).size!==names.length){error.textContent='Give each player a different, non-empty name.';return;}if(deck.length<5||deck.length>60||deck.some(x=>x.length>32)){error.textContent='Enter 5–60 unique topics, one per line, up to 32 characters each.';return;}state={version:2,names,deck,deckName:setup.deck,timerSeconds:setup.timerSeconds,round:0,history:[],used:[],phase:'handoff-rank',rankConfidence:60,guessConfidence:60};newRound();};
 if(saved)document.querySelector('#resume').onclick=()=>{state=saved;if(['rank','guess'].includes(state.phase)){pauseActiveTimer();state.returnPhase=state.phase;state.phase='shield';}render();};
}
function newRound(){let available=state.deck.filter(x=>!state.used.includes(x));if(available.length<5){available=[...state.deck];state.used=[];}state.timer=null;state.cards=shuffle(available).slice(0,5);state.used.push(...state.cards);state.secret=[...state.cards];state.guess=[...state.cards];state.rankConfidence=60;state.guessConfidence=60;state.revealed=0;state.current=null;state.phase='handoff-rank';render();}
function top(){let t=totals(state.history);if(state.phase==='reveal'&&state.current){const hits=state.current.matches.slice(0,state.revealed).filter(Boolean).length;t.team+=hits;t.game+=state.revealed-hits;}return `<div class="game-top"><span class="round-label">${state.round>=state.names.length?'OVERTIME · ':''}ROUND ${String(state.round+1).padStart(2,'0')} <span> / ${String(state.names.length).padStart(2,'0')}</span></span><div class="scoreboard" aria-label="Current score"><span class="team">Team <b>${t.team}</b></span><i>VS</i><span>Game <b>${t.game}</b></span></div><button class="quit" id="quit">Leave game ↗</button></div>`;}
function bindQuit(){document.querySelector('#quit')?.addEventListener('click',()=>{pauseActiveTimer();bindTimer();const d=document.createElement('dialog');d.innerHTML='<h2>Leaving the table?</h2><p>Your progress will be saved. You can continue from the home screen.</p><div class="confirm-buttons"><button class="secondary" id="stay">Keep playing</button><button class="primary" id="leave">Back to home</button></div>';document.body.append(d);d.showModal();d.querySelector('#stay').onclick=()=>{d.close();d.remove();};d.querySelector('#leave').onclick=()=>{save();saved=state;state=null;d.close();d.remove();renderSetup();};d.addEventListener('cancel',()=>d.remove());});}
function phases(active){return `<div class="phase-steps"><span class="${active===0?'active':''}">01 Secret ranking</span><span class="${active===1?'active':''}">02 Team guess</span><span class="${active===2?'active':''}">03 The reveal</span></div>`;}
function render(){save();if(state.phase.startsWith('handoff')||state.phase==='shield')renderHandoff();else if(state.phase==='rank'||state.phase==='guess')renderOrder();else if(state.phase==='reveal')renderReveal();else renderResult();bindQuit();}
function renderHandoff(){const rank=state.phase==='handoff-rank'||(state.phase==='shield'&&state.returnPhase==='rank');const resume=state.phase==='shield';mount(top()+`<section class="handoff"><div class="back-card">${rank?'B':'?'}</div><span class="eyebrow">${resume?'WELCOME BACK':'PASS THE DEVICE'}</span><h2>${rank?`Pass the device to<br>${esc(name())}`:'Time for a team huddle.'}</h2><p>${rank?'Everyone else, look away.<br>Rank by your own taste. There’s no wrong answer.':`${esc(name())} has locked in a ranking.<br>Pass the device to the others and let them discuss.`}</p><button class="primary" id="ready">${rank?`I’m ${esc(name())} — ready`:'We’re ready to guess'} <span>→</span></button><p class="micro">${rank?'Only the ranker should see the next screen.':'Ranker: keep a straight face. No hints!'}</p></section>`);document.querySelector('#ready').onclick=()=>{state.phase=rank?'rank':'guess';if(resume&&state.timer&&state.timer.remaining>0)resumeTimer(state.timer);delete state.returnPhase;render();};}
function confidence(rank){const key=rank?'rankConfidence':'guessConfidence';return `<div><label class="confidence-label" for="confidence"><span>${rank?'How many do you think they’ll match?':'How many do you think you’ll match?'}</span><output id="confidence-output" for="confidence">${state[key]}%</output></label><input id="confidence" type="range" min="0" max="100" step="10" value="${state[key]}"><div class="range-caption"><span>0% · Not a single match</span><span>100% · All five</span></div></div>`;}
function rankCells(order){return order.map((item,i)=>`<div class="rank-cell" style="--tier:${COLORS[i]}"><div class="rank-tier"><b>${i+1}</b>${TIERS[i]}</div><span class="rank-name">${esc(item)}</span><div class="reorder"><button data-from="${i}" data-to="${i-1}" aria-label="${esc(item)} move up" ${i===0?'disabled':''}>←</button><button data-from="${i}" data-to="${i+1}" aria-label="${esc(item)} move down" ${i===4?'disabled':''}>→</button></div></div>`).join('');}
function renderOrder(){const rank=state.phase==='rank',key=rank?'secret':'guess';mount(top()+phases(rank?0:1)+`<div class="play-heading"><div><h2>${rank?`${esc(name())}, rank your favorites.`:`How well do you know ${esc(name())}?`}</h2><p>${rank?'Put these in order, from love it to leave it.':'Talk it over. Put the cards in their order of preference.'}<br>Use the arrows to swap cards. 1 = favorite, 5 = least favorite.</p></div><span class="pill">${rank?'FOR YOUR EYES ONLY':'ONE SHARED TEAM GUESS'}</span></div>${timerMarkup()}<div id="scene" class="scene play-scene" aria-hidden="true"></div><div class="rank-grid" id="rank-grid">${rankCells(state[key])}</div><div class="bottom-panel">${confidence(rank)}<div><button class="primary" id="lock">${rank?'Lock ranking & pass it on':'Lock guess & reveal'} <span>→</span></button><p class="micro">No changes once you lock it in.</p></div></div>`);scene(state[key]);bindMove(key);bindTimer();document.querySelector('#confidence').oninput=e=>{state[rank?'rankConfidence':'guessConfidence']=Number(e.target.value);document.querySelector('#confidence-output').textContent=e.target.value+'%';save();};document.querySelector('#lock').onclick=()=>{pauseActiveTimer();if(rank){state.phase='handoff-guess';state.guess=[...state.cards];}else{state.current=evaluate(state.secret,state.guess,state.rankConfidence,state.guessConfidence);state.phase='reveal';state.revealed=0;}render();};}
function bindMove(key){document.querySelectorAll('[data-from]').forEach(b=>b.onclick=()=>{const from=Number(b.dataset.from),to=Number(b.dataset.to);state[key]=swap(state[key],from,to);save();table.update(state[key]);document.querySelector('#rank-grid').innerHTML=rankCells(state[key]);bindMove(key);const focus=document.querySelector(`[data-from="${to}"][data-to="${to+(to>from?1:-1)}"]`);(focus&&!focus.disabled?focus:document.querySelector(`[data-from="${to}"]:not(:disabled)`))?.focus({preventScroll:true});});}
function revealCells(){return state.guess.map((item,i)=>`<div class="rank-cell revealed" style="--tier:${COLORS[i]}"><div class="rank-tier"><b>${i+1}</b>${TIERS[i]}</div>${i<state.revealed?`<span class="rank-name">${esc(item)}</span><div class="answer-line">Their #${i+1}: ${esc(state.secret[i])}</div><div class="${state.current.matches[i]?'hit':'miss'}">${state.current.matches[i]?'Match · Team +1':'Miss · Game +1'}</div>`:'<div class="unknown">?</div>'}</div>`).join('');}
function renderReveal(){mount(top()+phases(2)+`<div class="play-heading"><div><h2>The truth is in the cards.</h2><p>One card at a time. Let’s see how well you know them.</p></div><span class="pill">${esc(name())}’s secret ranking</span></div><div id="scene" class="scene play-scene" aria-hidden="true"></div><div class="rank-grid" id="reveal-grid" aria-live="polite">${revealCells()}</div><div class="bottom-panel"><div class="reveal-summary" id="reveal-status">${revealStatus()}</div><div><button class="primary" id="flip">${state.revealed<5?`Reveal card ${state.revealed+1}`:'See your connection score'} <span>↗</span></button><p class="micro">One point per card · Only exact positions count</p></div></div>`);scene(state.secret,{concealed:true});table.update(state.secret,{revealed:state.revealed});document.querySelector('#flip').onclick=()=>{if(state.revealed<5){state.revealed++;save();table.update(state.secret,{revealed:state.revealed,flip:true});document.querySelector('#reveal-grid').innerHTML=revealCells();document.querySelector('#reveal-status').textContent=revealStatus();const oldTop=document.querySelector('.game-top');oldTop.outerHTML=top();bindQuit();document.querySelector('#flip').innerHTML=`${state.revealed<5?`Reveal card ${state.revealed+1}`:'See your connection score'} <span>↗</span>`;ping(state.current.matches[state.revealed-1]);}else{state.history.push({...state.current,ranker:name(),rankConfidence:state.rankConfidence,guessConfidence:state.guessConfidence});state.phase='result';render();}};}
function revealStatus(){const hits=state.current.matches.slice(0,state.revealed).filter(Boolean).length;return state.revealed?`Revealed ${state.revealed} / 5 · Matched ${hits}${state.revealed===5?'. Now tell us the story behind that ranking.':''}`:'Hold the explanations. Flip a card and let the surprises begin.';}
function renderResult(){const end=outcome(state.history,state.names.length),last=state.history.at(-1),done=['win','lose'].includes(end);const index=done?Math.round(state.history.reduce((s,r)=>s+r.index,0)/state.history.length):last.index;const acc=done?state.history.reduce((s,r)=>s+r.accuracy,0)/state.history.length:last.accuracy;const calibration=done?state.history.reduce((s,r)=>s+r.calibration,0)/state.history.length:last.calibration;mount(top()+`<div class="result-layout"><section><span class="eyebrow">${done?'THE FINAL SCORE':'A LITTLE CLOSER NOW'}</span><h2 class="result-title">${end==='win'?'This time,<br><em>we won together.</em>':end==='lose'?'The game wins.<br><em>We’ll get you next time.</em>':end==='overtime'?'It’s a tie.<br><em>One more round?</em>':`Matched ${last.hits} ${last.hits===1?'card':'cards'}.<br><em>${last.hits>=3?'You really get me.':'Well, that explains a lot.'}</em>`}</h2><p class="result-copy">${done?'One team. One result. There’s no right taste, just a little more to learn about each other.':`${esc(last.ranker)}’s round is complete. Team +${last.hits}, Game +${last.misses}.<br>Take a moment to share the story behind the order.`}</p><div class="round-history">${state.history.map((r,i)=>`<div class="history-row"><span>${String(i+1).padStart(2,'0')} / ${esc(r.ranker)}</span><b>Matched ${r.hits} / 5</b><span>Connection ${r.index}</span></div>`).join('')}</div><div class="result-actions">${done?'<button class="primary" id="again">Same people. New game ↗</button><button class="secondary" id="home">New setup</button>':`<button class="primary" id="next">${end==='overtime'?'Play overtime':`Up next: ${esc(state.names[(state.round+1)%state.names.length])}`} <span>→</span></button>`}</div></section><aside class="paper"><span class="eyebrow">${done?'TEAM CONNECTION':'ROUND CONNECTION'}</span><h2>${done?'Overall':'Round'} connection score</h2><div class="index-number">${index}<small> / 100</small></div><p class="intro">Know the answers. Know your confidence.</p><div class="metric-row"><span>Matches · 40% weight</span><strong>${Math.round(acc*100)}%</strong></div><div class="metric-row"><span>Confidence · 60% weight</span><strong>${Math.round(calibration*100)}%</strong></div>${!done?`<div class="metric-row"><span>Ranker / team prediction</span><strong>${last.rankConfidence}% / ${last.guessConfidence}%</strong></div>`:''}<p class="micro">${done?'Average of all round scores':'40 × match rate + 60 × confidence accuracy'}<br>Connection scores are for reflection, not victory points.</p></aside></div>`);if(done){document.querySelector('#again').onclick=()=>{state.history=[];state.round=0;state.used=[];newRound();};document.querySelector('#home').onclick=()=>{saved=null;state=null;try{localStorage.removeItem(KEY);}catch{}renderSetup();};}else document.querySelector('#next').onclick=()=>{state.round++;newRound();};}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state&&['rank','guess'].includes(state.phase)){pauseActiveTimer();state.returnPhase=state.phase;state.phase='shield';render();}});
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(state){pauseActiveTimer();save();saved=state;state=null;}renderSetup();};
function timerMarkup(){return (state.timerSeconds??90)>0?`<section class="turn-timer" aria-label="Turn timer"><div class="timer-clock"><span class="timer-label">TURN TIMER</span><output id="timer-clock" aria-label="Time remaining">${formatTime((state.timerSeconds??90)*1000)}</output></div><p id="timer-status" role="status">Time to think it over.</p><div class="timer-actions"><button id="timer-pause" class="secondary">Pause</button><button id="timer-add" class="secondary">+30 sec</button></div></section>`:'';}
function pauseActiveTimer(){if(state?.timer){pauseTimer(state.timer);save();}clearInterval(timerInterval);timerInterval=null;}
function bindTimer(){
 if(!document.querySelector('#timer-clock'))return;
 const id=`${state.round}:${state.phase}`;
 if(!state.timer||state.timer.id!==id){state.timer=startTimer(state.timerSeconds??90,id);save();}
 const clock=document.querySelector('#timer-clock'),status=document.querySelector('#timer-status'),button=document.querySelector('#timer-pause'),bar=document.querySelector('.turn-timer');
 function update(){const t=state.timer,ms=remaining(t);clock.textContent=formatTime(ms);bar.classList.toggle('timer-low',ms<=10000);button.textContent=t.running?'Pause':'Resume';button.disabled=ms===0;const message=ms===0?'Time’s up. Lock it in, or add more time.':t.running?'Time to think it over.':'Paused. Take your time.';if(status.textContent!==message)status.textContent=message;if(ms===0&&!t.alerted){pauseTimer(t);t.alerted=true;save();ping(false);}}
 button.onclick=()=>{if(state.timer.running)pauseTimer(state.timer);else resumeTimer(state.timer);save();update();};
 document.querySelector('#timer-add').onclick=()=>{addTime(state.timer,30);save();update();};
 update();timerInterval=setInterval(update,250);
}
window.addEventListener('pagehide',pauseActiveTimer);
renderSetup();
